-- ============================================================================
-- COURSE SEED DATA + BADGE SYSTEM
-- 3 kurs: Nybegynner (5 leksjoner), Middels (7 leksjoner), Avansert (10 leksjoner)
-- ============================================================================

-- ============================================================================
-- 1. BADGE SYSTEM
-- ============================================================================
CREATE TABLE IF NOT EXISTS course_badges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    module_id UUID UNIQUE NOT NULL REFERENCES course_modules(id) ON DELETE CASCADE,
    badge_emoji TEXT NOT NULL DEFAULT '🎓',
    badge_label_no TEXT NOT NULL,
    badge_label_en TEXT NOT NULL,
    badge_description_no TEXT,
    badge_description_en TEXT,
    badge_color TEXT NOT NULL DEFAULT 'from-blue-500 to-purple-600',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

COMMENT ON TABLE course_badges IS 'Badges awarded upon course/module completion';
COMMENT ON COLUMN course_badges.badge_emoji IS 'Emoji shown on the badge (e.g. 🚀, 💎, 📊)';
COMMENT ON COLUMN course_badges.badge_color IS 'Tailwind gradient class for badge background';

ALTER TABLE course_badges ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS course_badges_select_published ON course_badges;
CREATE POLICY course_badges_select_published ON course_badges
    FOR SELECT TO public
    USING (true);

-- Add earned_at to user_lesson_progress if not present (for badge timing)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public'
        AND table_name = 'user_lesson_progress'
        AND column_name = 'course_completed_at'
    ) THEN
        ALTER TABLE user_lesson_progress ADD COLUMN course_completed_at TIMESTAMPTZ;
    END IF;
END $$;

-- ============================================================================
-- 2. USER BADGE TABLE — tracks which badges a user has earned
-- ============================================================================
CREATE TABLE IF NOT EXISTS user_badges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    badge_id UUID NOT NULL REFERENCES course_badges(id) ON DELETE CASCADE,
    earned_at TIMESTAMPTZ DEFAULT NOW(),
    is_displayed BOOLEAN DEFAULT true,
    UNIQUE(user_id, badge_id)
);

COMMENT ON TABLE user_badges IS 'Badges earned by users through course completion';

ALTER TABLE user_badges ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS user_badges_select_own ON user_badges;
CREATE POLICY user_badges_select_own ON user_badges
    FOR SELECT TO authenticated
    USING (user_id = auth.uid());

DROP POLICY IF EXISTS user_badges_insert_own ON user_badges;
CREATE POLICY user_badges_insert_own ON user_badges
    FOR INSERT TO authenticated
    WITH CHECK (user_id = auth.uid());

CREATE INDEX IF NOT EXISTS idx_user_badges_user ON user_badges(user_id);
CREATE INDEX IF NOT EXISTS idx_user_badges_badge ON user_badges(badge_id);

-- ============================================================================
-- 3. FUNCTION: award_badge_on_course_completion
-- ============================================================================
CREATE OR REPLACE FUNCTION award_badge_on_course_completion()
RETURNS TRIGGER AS $$
DECLARE
    v_module_id UUID;
    v_total_lessons INT;
    v_completed_lessons INT;
    v_badge_id UUID;
BEGIN
    -- Get the module_id for this lesson
    SELECT module_id INTO v_module_id FROM course_lessons WHERE id = NEW.lesson_id;
    IF v_module_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Count total published lessons in module
    SELECT COUNT(*) INTO v_total_lessons
    FROM course_lessons
    WHERE module_id = v_module_id AND is_published = true;

    -- Count completed lessons for this user in module
    SELECT COUNT(*) INTO v_completed_lessons
    FROM user_lesson_progress ulp
    JOIN course_lessons cl ON ulp.lesson_id = cl.id
    WHERE cl.module_id = v_module_id
    AND ulp.user_id = NEW.user_id
    AND ulp.status = 'completed';

    -- If all lessons completed, award badge
    IF v_completed_lessons >= v_total_lessons AND v_total_lessons > 0 THEN
        -- Find the badge for this module
        SELECT id INTO v_badge_id FROM course_badges WHERE module_id = v_module_id;

        IF v_badge_id IS NOT NULL THEN
            -- Award badge if not already earned (idempotent)
            INSERT INTO user_badges (user_id, badge_id)
            VALUES (NEW.user_id, v_badge_id)
            ON CONFLICT (user_id, badge_id) DO NOTHING;

            -- Mark course completion time
            UPDATE user_lesson_progress
            SET course_completed_at = NOW()
            WHERE user_id = NEW.user_id
            AND lesson_id IN (
                SELECT id FROM course_lessons WHERE module_id = v_module_id
            )
            AND course_completed_at IS NULL;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger for badge award on lesson completion
DROP TRIGGER IF EXISTS trigger_award_badge_on_completion ON user_lesson_progress;
CREATE TRIGGER trigger_award_badge_on_completion
    AFTER INSERT OR UPDATE OF status ON user_lesson_progress
    FOR EACH ROW
    WHEN (NEW.status = 'completed')
    EXECUTE FUNCTION award_badge_on_course_completion();

