('nybegynner', 'Nybegynner', 'Beginner', 'Lær det grunnleggende om kryptovaluta, sikkerhet og din første handel. Perfekt for deg som aldri har kjøpt krypto før.', 'Learn the basics of cryptocurrency, security, and your first trade. Perfect for complete beginners.', '🚀', 'beginner', 45, true, 1, true),
('middels', 'Middels', 'Intermediate', 'Bygg videre på grunnkunnskapene. Lær om markedsanalyse, risiko, DeFi og skatt.', 'Build on your foundational knowledge. Learn about market analysis, risk, DeFi and taxes.', '📊', 'intermediate', 85, false, 2, true),
('avansert', 'Avansert', 'Advanced', 'Avanserte strategier for erfarne tradere. Futures, yield farming, arbitrage og automatiserte strategier.', 'Advanced strategies for experienced traders. Futures, yield farming, arbitrage and automated strategies.', '💎', 'advanced', 150, false, 3, true)
