-- ============================================================================
-- 5. SEED: course_lessons for Nybegynner (5 leksjoner)
-- ============================================================================
DO $$
DECLARE
    v_module_id UUID;
BEGIN
    SELECT id INTO v_module_id FROM course_modules WHERE slug = 'nybegynner';

    IF v_module_id IS NOT NULL THEN
        INSERT INTO course_lessons (module_id, slug, title_no, title_en, content_no, content_en, estimated_minutes, sort_order, is_published) VALUES

        (v_module_id, 'hva-er-krypto', 'Hva er kryptovaluta?', 'What is Cryptocurrency?',
        E'# Hva er kryptovaluta?\n\nKryptovaluta er **digitale penger** som fungerer uten banker eller myndigheter. I motsetning til norske kroner, som kontrolleres av Norges Bank, styres kryptovaluta av et globalt nettverk av datamaskiner.\n\n## Hvordan fungerer det?\n\n- **Desentralisert** — ingen enkeltperson eller organisasjon kontrollerer systemet\n- **Sikker** — transaksjoner er kryptert og kan ikke endres i ettertid\n- **Globalt** — du kan sende penger til hvem som helst, hvor som helst, når som helst\n- **Gjennomsiktig** — alle transaksjoner er synlige på blokkjeden\n\n## Hvorfor er krypto verdt noe?\n\nAkkurat som gull har begrenset tilgang, har Bitcoin en **maksgrense på 21 millioner mynter** som noensinne vil eksistere. Denne knappheten, kombinert med at tusenvis av mennesker verden over ønsker å eie det, skaper verdi.\n\n## Viktige begreper\n\n| Begrep | Betydning |\n|--------|-----------|\n| **Blockchain** | En digital hovedbok som lagrer alle transaksjoner |\n| **Wallet** | En digital lommebok for å oppbevare krypto |\n| **Private key** | Ditt hemmelige passord som gir deg tilgang til kryptoen |\n| **Exchange** | En børs hvor du kan kjøpe og selge krypto |\n\n> 💡 **Tips:** Tenk på kryptovaluta som digitalt gull. Det er spekulativt, men har potensial for høy avkastning over tid.',
        E'# What is Cryptocurrency?\n\nCryptocurrency is **digital money** that works without banks or governments. Unlike Norwegian kroner, which is controlled by Norges Bank, cryptocurrency is run by a global network of computers.\n\n## How does it work?\n\n- **Decentralized** — no single person or organization controls the system\n- **Secure** — transactions are encrypted and cannot be changed afterwards\n- **Global** — you can send money to anyone, anywhere, anytime\n- **Transparent** — all transactions are visible on the blockchain\n\n## Why is crypto worth anything?\n\nJust like gold has limited supply, Bitcoin has a **maximum of 21 million coins** that will ever exist. This scarcity, combined with thousands of people worldwide wanting to own it, creates value.\n\n## Key terms\n\n| Term | Meaning |\n|------|---------|\n| **Blockchain** | A digital ledger that stores all transactions |\n| **Wallet** | A digital wallet to store crypto |\n| **Private key** | Your secret password giving you access to your crypto |\n| **Exchange** | A platform where you can buy and sell crypto |\n\n> 💡 **Tip:** Think of cryptocurrency as digital gold. It is speculative but has potential for high returns over time.',
        10, 1, true),

        (v_module_id, 'hvordan-kjope', 'Hvordan kjøpe krypto', 'How to Buy Crypto',
        E'# Hvordan kjøpe kryptovaluta\n\nÅ kjøpe din første kryptovaluta er enklere enn du tror! Her er steg-for-steg guiden.\n\n## Steg 1: Velg en børs\n\nDe mest populære børsene for nordmenn er:\n\n- **Firi** — Norsk børs, enkel å bruke, Vipps-integrasjon\n- **Coinbase** — Amerikansk børs, veldig brukervennlig\n- **Binance** — Verdens største børs, mange kryptovalutaer\n\n## Steg 2: Opprett konto\n\n- Registrer deg med e-post\n- Verifiser identiteten din (BankID for norske børsen)\n- Sett opp to-faktor autentisering (2FA)\n\n## Steg 3: Overfør penger\n\n- Bankoverføring eller Vipps (Firi)\n- Minste beløp: ofte 500 kr\n- Gebyrer: 0–1.5 % avhengig av betalingsmetode\n\n## Steg 4: Kjøp\n\n- Velg hva du vil kjøpe (f.eks. Bitcoin)\n- Velg beløp (du trenger ikke kjøpe en hel Bitcoin!)\n- Bekreft kjøpet\n\n## Steg 5: Oppbevar trygt\n\n- **La det stå på børsen** — enkelt, men risiko (børsen kan bli hacket)\n- **Flytt til egen lommebok** — tryggere, men mer ansvar\n\n> ⚠️ **Advarsel:** Invester aldri mer enn du har råd til å tape. Kryptovaluta er svært volatilt.',
        E'# How to Buy Cryptocurrency\n\nBuying your first cryptocurrency is easier than you think! Here is the step-by-step guide.\n\n## Step 1: Choose an exchange\n\nThe most popular exchanges for Norwegians are:\n\n- **Firi** — Norwegian exchange, easy to use, Vipps integration\n- **Coinbase** — American exchange, very user-friendly\n- **Binance** — World\'s largest exchange, many cryptocurrencies\n\n## Step 2: Create account\n\n- Register with email\n- Verify your identity (BankID for Norwegian exchanges)\n- Set up two-factor authentication (2FA)\n\n## Step 3: Deposit money\n\n- Bank transfer or Vipps\n- Minimum amount: often 500 NOK\n- Fees: 0–1.5 % depending on payment method\n\n## Step 4: Buy\n\n- Choose what to buy (e.g. Bitcoin)\n- Choose amount (you don\'t need to buy a whole Bitcoin!)\n- Confirm the purchase\n\n## Step 5: Store safely\n\n- **Leave it on the exchange** — easy, but risky (exchange can be hacked)\n- **Move to your own wallet** — safer, but more responsibility\n\n> ⚠️ **Warning:** Never invest more than you can afford to lose. Cryptocurrency is highly volatile.',
        10, 2, true),

        (v_module_id, 'hva-er-bitcoin', 'Hva er Bitcoin?', 'What is Bitcoin?',
        E'# Hva er Bitcoin?\n\nBitcoin ble skapt i 2009 av en anonym person (eller gruppe) under pseudonymet **Satoshi Nakamoto**. Det var verdens første kryptovaluta og er fortsatt den mest verdifulle.\n\n## Hvorfor er Bitcoin spesiell?\n\n- **Først ute** — banet vei for alle andre kryptovalutaer\n- **Maks 21 millioner** — det vil aldri finnes mer enn 21 millioner Bitcoin\n- **Desentralisert** — ingen myndighet kan trykke flere Bitcoins\n- **Sikker** — nettverket har aldri blitt hacket\n\n## Hvordan utvinnes Bitcoin?\n\nBitcoin "utvinnes" gjennom en prosess som kalles **mining**. Datamaskiner over hele verden konkurrerer om å løse komplekse matematiske oppgaver. Den som først løser oppgaven, får nye Bitcoin som belønning.\n\n## Bitcoin som verdilager\n\nMange kaller Bitcoin for **"digitalt gull"** fordi:\n\n- Det er knapt (bare 21 millioner noensinne)\n- Det kan ikke trykkes opp av myndigheter\n- Det er globalt og kan flyttes på tvers av landegrenser\n- Det har ingen korrelasjon med tradisjonelle markeder\n\n> 📖 **Visste du?** Den første Bitcoin-transaksjonen var for to pizzaer — 10 000 BTC for to Papa John\'s pizzaer i 2010. I dag er det verdt milliarder.',
        E'# What is Bitcoin?\n\nBitcoin was created in 2009 by an anonymous person (or group) under the pseudonym **Satoshi Nakamoto**. It was the world\'s first cryptocurrency and remains the most valuable.\n\n## Why is Bitcoin special?\n\n- **First mover** — paved the way for all other cryptocurrencies\n- **Max 21 million** — there will never be more than 21 million Bitcoin\n- **Decentralized** — no authority can print more Bitcoins\n- **Secure** — the network has never been hacked\n\n## How is Bitcoin mined?\n\nBitcoin is "mined" through a process called **mining**. Computers worldwide compete to solve complex math problems. The first to solve it gets new Bitcoin as a reward.\n\n## Bitcoin as a store of value\n\nMany call Bitcoin **"digital gold"** because:\n\n- It is scarce (only 21 million ever)\n- It cannot be printed by governments\n- It is global and can move across borders\n- It has no correlation with traditional markets\n\n> 📖 **Did you know?** The first Bitcoin transaction was for two pizzas — 10,000 BTC for two Papa John\'s pizzas in 2010. Today that would be worth billions.',
        10, 3, true),

        (v_module_id, 'sikkerhet', 'Sikkerhet', 'Security',
        E'# Sikkerhet — Beskytt kryptoen din\n\nKryptoverdenen tiltrekker seg både innovative investorer og dessverre også svindlere. Her er de viktigste sikkerhetsreglene.\n\n## To-faktor autentisering (2FA)\n\n- **Bruk ALLTID 2FA** på alle kryptobørser\n- **Bruk Google Authenticator eller Authy** — IKKE SMS (SMS kan kapres)\n- 2FA er din første forsvarslinje\n\n## Private nøkler\n\n- **Del ALDRI din private nøkkel** med noen — aldri, uansett grunn\n- Oppbevar den offline (skriv den ned på papir og oppbevar trygt)\n- Hvis du mister den, mister du tilgangen til kryptoen din permanent\n\n## Phishing\n\nSvindlere lager falske nettsider som ser ut som ekte børsen:\n\n- Sjekk ALLTID URL-en nøye\n- Aldri klikk på linker i epost som "bekreft kontoen din"\n- Bruk bokmerker til dine vanlige børsen\n\n## Passord\n\n- Bruk et **sterkt, unikt passord** for hver børs\n- Bruk en passordmanager (som 1Password, Bitwarden, eller Apple Passord)\n- Aktiver gjenopprettingskoder\n\n## Hardware wallet\n\nFor større beløp (>10 000 kr):\n\n- **Ledger** eller **Trezor** — fysiske enheter som holder kryptoen offline\n- Koster 500–2000 kr — en billig forsikring for større investeringer\n\n> 🛡️ **Huskeregelen:** Hvis noen lover garantert avkastning eller ber om din private nøkkel, er det svindel. Punktum.',
        E'# Security — Protect Your Crypto\n\nThe crypto world attracts both innovative investors and unfortunately also scammers. Here are the most important security rules.\n\n## Two-factor authentication (2FA)\n\n- **ALWAYS use 2FA** on all crypto exchanges\n- **Use Google Authenticator or Authy** — NOT SMS (SMS can be intercepted)\n- 2FA is your first line of defense\n\n## Private keys\n\n- **NEVER share your private key** with anyone — never, for any reason\n- Store it offline (write it on paper and store safely)\n- If you lose it, you lose access to your crypto permanently\n\n## Phishing\n\nScammers create fake websites that look like real exchanges:\n\n- ALWAYS check the URL carefully\n- Never click links in emails saying "confirm your account"\n- Use bookmarks for your regular exchanges\n\n## Passwords\n\n- Use a **strong, unique password** for each exchange\n- Use a password manager (like 1Password, Bitwarden, or Apple Passwords)\n- Enable recovery codes\n\n## Hardware wallet\n\nFor larger amounts (>10,000 NOK):\n\n- **Ledger** or **Trezor** — physical devices that keep crypto offline\n- Costs 500–2000 NOK — cheap insurance for larger investments\n\n> 🛡️ **The rule:** If someone promises guaranteed returns or asks for your private key, it is a scam. Period.',
        10, 4, true),

        (v_module_id, 'forste-trade', 'Din første trade', 'Your First Trade',
        E'# Din første trade\n\nGratulerer! Du har lært det grunnleggende. Nå er det på tide å gjøre din første handel.\n\n## Før du begynner\n\n1. **Start smått** — handel med et beløp du er komfortabel med å tape\n2. **Bruk paper trading** — Klarpakke har et virtuelt miljø hvor du kan øve uten risiko\n3. **Ha en plan** — vet når du skal kjøpe og når du skal selge\n\n## Hvordan plassere en trade\n\n1. Velg hva du vil handle (f.eks. BTC/NOK)\n2. Velg **kjøp** eller **salg**\n3. Angi beløp\n4. Velg ordretype:\n   - **Markedsordre** — kjøp/selg umiddelbart til gjeldende pris\n   - **Limitordre** — sett en pris du vil handle til (venter til prisen treffer målet)\n5. Bekreft handelen\n\n## Din første strategi\n\nFor din første handel, prøv **Dollar Cost Averaging (DCA)**:\n\n> Kjøp for et fast beløp hver uke/måned, uansett pris. Dette jevner ut svingningene.\n\nEksempel: Kjøp for **500 kr** i Bitcoin **hver fredag** i 3 måneder.\n\n## Hva du bør følge med på\n\n- **Prisen** — følg med på markedet\n- **Volum** — høyt volum = mye aktivitet\n- **Nyheter** — regulering, teknologiske fremskritt\n- **Din egen følelse** — ikke la frykt eller grådighet styre\n\n> ✅ **Neste steg:** Når du har gjort din første handel, gå videre til Middels-kurset for å lære mer.',
        E'# Your First Trade\n\nCongratulations! You have learned the basics. Now it is time to make your first trade.\n\n## Before you start\n\n1. **Start small** — trade with an amount you are comfortable losing\n2. **Use paper trading** — Klarpakke has a virtual environment where you can practice without risk\n3. **Have a plan** — know when to buy and when to sell\n\n## How to place a trade\n\n1. Choose what to trade (e.g., BTC/NOK)\n2. Choose **buy** or **sell**\n3. Enter amount\n4. Choose order type:\n   - **Market order** — buy/sell immediately at current price\n   - **Limit order** — set a price you want to trade at (waits until price hits target)\n5. Confirm the trade\n\n## Your first strategy\n\nFor your first trade, try **Dollar Cost Averaging (DCA)**:\n\n> Buy a fixed amount every week/month, regardless of price. This smooths out the fluctuations.\n\nExample: Buy **500 NOK** worth of Bitcoin **every Friday** for 3 months.\n\n## What to watch\n\n- **Price** — follow the market\n- **Volume** — high volume = lots of activity\n- **News** — regulation, technological advances\n- **Your own feelings** — don\'t let fear or greed control you\n\n> ✅ **Next step:** Once you have made your first trade, move on to the Intermediate course to learn more.',
        10, 5, true);
    END IF;
END $$;

-- ============================================================================
-- 6. SEED: course_lessons for Middels (7 leksjoner)
-- ============================================================================
DO $$
DECLARE
    v_module_id UUID;
BEGIN
    SELECT id INTO v_module_id FROM course_modules WHERE slug = 'middels';

    IF v_module_id IS NOT NULL THEN
        INSERT INTO course_lessons (module_id, slug, title_no, title_en, content_no, content_en, estimated_minutes, sort_order, is_published) VALUES

        (v_module_id, 'blockchain-dypt', 'Blockchain i dybden', 'Blockchain Deep Dive',
        E'# Blockchain i dybden\n\nBlockchain er teknologien som driver ALL kryptovaluta. La oss se nærmere på hvordan den fungerer.\n\n## Hva er en blokkjede?\n\nSe for deg en digital hovedbok som kopieres til tusenvis av datamaskiner samtidig:\n\n- Hver "blokk" inneholder en gruppe med transaksjoner\n- Blokker lenkes sammen kronologisk (derav "blokkjede")\n- Når en blokk er lagt til, kan den aldri endres\n\n## Konsensusmekanismer\n\nFor at alle datamaskinene skal bli enige om hva som står i blokkjeden, brukes en konsensusmekanisme:\n\n### Proof of Work (PoW)\n- Brukes av Bitcoin\n- "Miners" løser komplekse matteoppgaver\n- Krever mye strøm, men er svært sikker\n\n### Proof of Stake (PoS)\n- Brukes av Ethereum (etter "The Merge")\n- Validatorer "satser" (låser) mynter som sikkerhet\n- Mye mer energieffektivt enn PoW\n\n## Hvorfor er blockchain viktig?\n\n1. **Tillit** — du trenger ikke stole på en bank eller tredjepart\n2. **Gjennomsiktighet** — alle kan sjekke transaksjonshistorikken\n3. **Sikkerhet** — ekstremt vanskelig å manipulere\n4. **Tilgjengelighet** — hvem som helst kan delta\n\n> 🔗 **Visste du?** Ethereum-blochkjedden behandler over 1 million transaksjoner daglig.',
        E'# Blockchain Deep Dive\n\nBlockchain is the technology powering ALL cryptocurrency. Let us take a closer look at how it works.\n\n## What is a blockchain?\n\nImagine a digital ledger that is copied to thousands of computers simultaneously:\n\n- Each "block" contains a group of transactions\n- Blocks are linked together chronologically (hence "blockchain")\n- Once a block is added, it can never be changed\n\n## Consensus mechanisms\n\nFor all computers to agree on what is in the blockchain, a consensus mechanism is used:\n\n### Proof of Work (PoW)\n- Used by Bitcoin\n- "Miners" solve complex math problems\n- Requires lots of energy, but is very secure\n\n### Proof of Stake (PoS)\n- Used by Ethereum (after "The Merge")\n- Validators "stake" (lock) coins as collateral\n- Much more energy efficient than PoW\n\n## Why is blockchain important?\n\n1. **Trust** — you don\'t need to trust a bank or third party\n2. **Transparency** — anyone can check the transaction history\n3. **Security** — extremely difficult to manipulate\n4. **Accessibility** — anyone can participate\n\n> 🔗 **Did you know?** The Ethereum blockchain processes over 1 million transactions daily.',
        12, 1, true),

        (v_module_id, 'markedsanalyse', 'Markedsanalyse', 'Market Analysis',
        E'# Markedsanalyse\n\nFor å bli en lønnsom trader må du forstå markedet du handler i.\n\n## To hovedtyper analyse\n\n### Fundamental analyse (FA)\nSer på den underliggende verdien:\n- Prosjektets team og teknologi\n- Partnerskap og brukeradopsjon\n- Konkurrenter og markedsandel\n- Tokenomics (hvordan tilbud og etterspørsel fungerer)\n\n### Teknisk analyse (TA)\nSer på prishistorikk og mønstre:\n- Grafer og prisdiagrammer\n- Indikatorer (RSI, MACD, glidende gjennomsnitt)\n- Volumanalyse\n- Støtte- og motstandsnivåer\n\n## Markedssykluser\n\nKryptomarkedet beveger seg i sykluser:\n\n1. **Akkumulering** — pris er lav, smarte investorer kjøper\n2. **Opptrend (bull run)** — prisen stiger, FOMO tiltrekker nye kjøpere\n3. **Distribusjon** — tidlige investorer selger til sent ankomne\n4. **Nedtrend (bear market)** — prisen faller, frykt sprer seg\n\n> 📈 **Tips:** Lær å kjenne igjen hvilken fase markedet er i. Det hjelper deg å ta bedre beslutninger.',
        E'# Market Analysis\n\nTo become a profitable trader you must understand the market you trade in.\n\n## Two main types of analysis\n\n### Fundamental Analysis (FA)\nLooks at the underlying value:\n- The project\'s team and technology\n- Partnerships and user adoption\n- Competitors and market share\n- Tokenomics (how supply and demand work)\n\n### Technical Analysis (TA)\nLooks at price history and patterns:\n- Charts and price diagrams\n- Indicators (RSI, MACD, moving averages)\n- Volume analysis\n- Support and resistance levels\n\n## Market cycles\n\nThe crypto market moves in cycles:\n\n1. **Accumulation** — price is low, smart investors buy\n2. **Uptrend (bull run)** — price rises, FOMO attracts new buyers\n3. **Distribution** — early investors sell to latecomers\n4. **Downtrend (bear market)** — price falls, fear spreads\n\n> 📈 **Tip:** Learn to recognize which phase the market is in. It helps you make better decisions.',
        12, 2, true),

        (v_module_id, 'tekniske-indikatorer', 'Tekniske Indikatorer', 'Technical Indicators',
        E'# Tekniske Indikatorer\n\nTekniske indikatorer hjelper deg å forutsi prisbevegelser basert på historiske data.\n\n## RSI (Relative Strength Index)\n\nMåler hvor "overkjøpt" eller "oversolgt" et marked er:\n\n- **Over 70** — overkjøpt, kan være på tide å selge\n- **Under 30** — oversolgt, kan være på tide å kjøpe\n- RSI 14 er standardinnstillingen (ser på 14 perioder)\n\n## Glidende gjennomsnitt (MA)\n\nJevner ut prissvingninger for å se trenden:\n\n- **MA 50** — 50-dagers gjennomsnitt (kortsiktig trend)\n- **MA 200** — 200-dagers gjennomsnitt (langsiktig trend)\n- **Golden cross** — MA 50 krysser over MA 200 = bullish signal\n- **Death cross** — MA 50 krysser under MA 200 = bearish signal\n\n## MACD (Moving Average Convergence Divergence)\n\nViser forholdet mellom to glidende gjennomsnitt:\n\n- **MACD-linje** krysser over **signallinje** = kjøpssignal\n- **MACD-linje** krysser under **signallinje** = salgssignal\n- **Histogram** viser styrken i trenden\n\n## Bollinger Bands\n\nViser volatilitet og potensielle prisnivåer:\n\n- Smale bånd = lav volatilitet (forventet stort utbrudd)\n- Bredde bånd = høy volatilitet\n- Pris som berører øvre bånd = overkjøpt\n- Pris som berører nedre bånd = oversolgt\n\n> ⚡ **Husk:** Ingen indikator er 100% nøyaktig. Bruk flere indikatorer sammen for bedre signaler.',
        E'# Technical Indicators\n\nTechnical indicators help you predict price movements based on historical data.\n\n## RSI (Relative Strength Index)\n\nMeasures how "overbought" or "oversold" a market is:\n\n- **Above 70** — overbought, may be time to sell\n- **Below 30** — oversold, may be time to buy\n- RSI 14 is the standard setting (looks at 14 periods)\n\n## Moving Averages (MA)\n\nSmooths out price fluctuations to see the trend:\n\n- **MA 50** — 50-day average (short-term trend)\n- **MA 200** — 200-day average (long-term trend)\n- **Golden cross** — MA 50 crosses above MA 200 = bullish signal\n- **Death cross** — MA 50 crosses below MA 200 = bearish signal\n\n## MACD (Moving Average Convergence Divergence)\n\nShows the relationship between two moving averages:\n\n- **MACD line** crosses above **signal line** = buy signal\n- **MACD line** crosses below **signal line** = sell signal\n- **Histogram** shows trend strength\n\n## Bollinger Bands\n\nShows volatility and potential price levels:\n\n- Narrow bands = low volatility (expect big breakout)\n- Wide bands = high volatility\n- Price touching upper band = overbought\n- Price touching lower band = oversold\n\n> ⚡ **Remember:** No indicator is 100% accurate. Use multiple indicators together for better signals.',
        15, 3, true),

        (v_module_id, 'risiko-og-belonning', 'Risiko og Belønning', 'Risk and Reward',
        E'# Risiko og Belønning\n\nDen viktigste ferdigheten en trader kan lære er risikostyring.\n\n## Risk/Reward Ratio\n\nForholdet mellom potensiell gevinst og potensielt tap:\n\n- **1:2** — risikerer 100 kr for å tjene 200 kr (bra)\n- **1:1** — risikerer 100 kr for å tjene 100 kr (nøytralt)\n- **2:1** — risikerer 200 kr for å tjene 100 kr (dårlig)\n\n> ⚖️ **Regel:** Aldri ta en trade med dårligere enn 1:2 risk/reward.\n\n## Position Sizing\n\nHvor mye av porteføljen din skal du risikere per trade?\n\n- **1% regelen** — risiker maks 1% av total portefølje per trade\n- Eksempel: Har du 10 000 kr, risikerer du maks 100 kr per trade\n\n## Stop Loss\n\nEn automatisk ordre som selger hvis prisen faller til et visst nivå:\n\n- Sett stop loss **før** du går inn i en trade\n- Flytt stop loss opp når prisen stiger (trailing stop)\n- Ikke flytt stop loss ned (det ødelegger formålet)\n\n## Take Profit\n\nEn automatisk ordre som selger når prisen når målet ditt:\n\n- Ha et realistisk mål basert på teknisk analyse\n- Ta delvis profitt underveis (50% ved første mål)\n- La resten løpe hvis trenden er sterk\n\n> 🛑 **Husk:** Det er bedre å gå glipp av en trade enn å tape penger. Disiplin er nøkkelen.',
        E'# Risk and Reward\n\nThe most important skill a trader can learn is risk management.\n\n## Risk/Reward Ratio\n\nThe ratio between potential gain and potential loss:\n\n- **1:2** — risk 100 NOK to earn 200 NOK (good)\n- **1:1** — risk 100 NOK to earn 100 NOK (neutral)\n- **2:1** — risk 200 NOK to earn 100 NOK (bad)\n\n> ⚖️ **Rule:** Never take a trade with worse than 1:2 risk/reward.\n\n## Position Sizing\n\nHow much of your portfolio should you risk per trade?\n\n- **1% rule** — risk max 1% of total portfolio per trade\n- Example: If you have 10,000 NOK, risk max 100 NOK per trade\n\n## Stop Loss\n\nAn automatic order that sells if the price drops to a certain level:\n\n- Set stop loss **before** you enter a trade\n- Move stop loss up as the price rises (trailing stop)\n- Don\'t move stop loss down (it defeats the purpose)\n\n## Take Profit\n\nAn automatic order that sells when the price reaches your target:\n\n- Have a realistic target based on technical analysis\n- Take partial profit along the way (50% at first target)\n- Let the rest run if the trend is strong\n\n> 🛑 **Remember:** It is better to miss a trade than to lose money. Discipline is key.',
        12, 4, true),

        (v_module_id, 'portefoljediversifisering', 'Porteføljediversifisering', 'Portfolio Diversification',
        E'# Porteføljediversifisering\n\nIkke legg alle eggene i samme kurv — dette gjelder spesielt i kryptomarkedet.\n\n## Hvorfor diversifisere?\n\n- **Redusere risiko** — hvis én kryptovaluta faller, kan en annen stige\n- **Fange vekst** — du vet aldri hvilken mynt som blir neste store\n- **Sov bedre om natten** — mindre volatilitet i totalporteføljen\n\n## Hvordan bygge en portefølje\n\n### Kjerne (60-70%)\n- Bitcoin (BTC) — markedets ankermann\n- Ethereum (ETH) — plattformen for desentraliserte apper\n\n### Vekst (20-30%)\n- Etablerte altcoins: Solana, Cardano, Polkadot\n- Løser reelle problemer med aktiv utvikling\n\n### Spekulativ (5-10%)\n- Mindre mynter med høy risiko/høy belønning\n- Aldri mer enn du har råd til å tape\n\n## Rebalansering\n\nJustér porteføljen jevnlig:\n\n- Månedlig: sjekk at fordelingen fortsatt stemmer\n- Hvis en mynt har vokst seg til 50% av porteføljen, selg noe\n- Hvis en mynt har falt mye, vurder å kjøpe mer (DCA)\n\n> 📊 **Tips:** En balansert portefølje overlever et bear market mye bedre enn en som satser alt på én mynt.',
        E'# Portfolio Diversification\n\nDon\'t put all your eggs in one basket — this is especially true in the crypto market.\n\n## Why diversify?\n\n- **Reduce risk** — if one cryptocurrency falls, another may rise\n- **Capture growth** — you never know which coin will be the next big thing\n- **Sleep better at night** — less volatility in total portfolio\n\n## How to build a portfolio\n\n### Core (60-70%)\n- Bitcoin (BTC) — the market anchor\n- Ethereum (ETH) — platform for decentralized apps\n\n### Growth (20-30%)\n- Established altcoins: Solana, Cardano, Polkadot\n- Solves real problems with active development\n\n### Speculative (5-10%)\n- Smaller coins with high risk/high reward\n- Never more than you can afford to lose\n\n## Rebalancing\n\nAdjust your portfolio regularly:\n\n- Monthly: check that the allocation still matches\n- If one coin has grown to 50% of the portfolio, sell some\n- If one coin has fallen a lot, consider buying more (DCA)\n\n> 📊 **Tip:** A balanced portfolio survives a bear market much better than one that goes all-in on a single coin.',
        10, 5, true),

        (v_module_id, 'skatt-og-regulering', 'Skatt og Regulering', 'Tax and Regulation',
        E'# Skatt og Regulering\n\nI Norge er kryptovaluta skattepliktig. Det er viktig å forstå reglene for å unngå problemer med Skatteetaten.\n\n## Skatt på kryptovaluta i Norge\n\n- **Gevinst** — skattepliktig som alminnelig inntekt (22%)\n- **Tap** — fradragsberettiget\n- **Realisasjonsprinsippet** — du skatter først når du selger\n\n## Hva må du rapportere?\n\n- Hver eneste handel du gjør (kjøp, salg, bytte)\n- Gevinst og tap per transaksjon\n- Beholdning per 31.12 hvert år\n\n## Verktøy som hjelper\n\n- **Kryptosekken** — norsk tjeneste som beregner skatten for deg\n- **CoinTracker** — internasjonal, støtter mange børsen\n- **Accointing** — gratis for inntil 25 transaksjoner\n\n## Hvitvaskingsloven\n\nNorske kryptobørsen (som Firi) må følge hvitvaskingsloven:\n\n- De må verifisere identiteten din\n- De rapporterer mistenkelige transaksjoner til Økokrim\n- Det er derfor du må BankID-verifisere deg\n\n> ⚠️ **Viktig:** Ikke prøv å skjule kryptoinntekter for Skatteetaten. De har verktøy for å oppdage det, og straffen er høy.',
        E'# Tax and Regulation\n\nIn Norway, cryptocurrency is taxable. It is important to understand the rules to avoid problems with the Tax Administration.\n\n## Tax on cryptocurrency in Norway\n\n- **Gain** — taxable as ordinary income (22%)\n- **Loss** — tax deductible\n- **Realization principle** — you only tax when you sell\n\n## What must you report?\n\n- Every single trade you make (buy, sell, swap)\n- Gain and loss per transaction\n- Holdings as of Dec 31 each year\n\n## Tools that help\n\n- **Kryptosekken** — Norwegian service that calculates taxes for you\n- **CoinTracker** — international, supports many exchanges\n- **Accointing** — free for up to 25 transactions\n\n## Anti-money laundering law\n\nNorwegian crypto exchanges (like Firi) must follow AML laws:\n\n- They must verify your identity\n- They report suspicious transactions to authorities\n- This is why you must BankID verify yourself\n\n> ⚠️ **Important:** Don\'t try to hide crypto income from the Tax Administration. They have tools to detect it, and the penalties are severe.',
        12, 6, true),

        (v_module_id, 'defi-grunnleggende', 'DeFi — Desentralisert Finans', 'DeFi — Decentralized Finance',
        E'# DeFi — Desentralisert Finans\n\nDeFi er en av de mest spennende innovasjonene i kryptoverdenen. Det handler om å erstatte tradisjonelle finansielle tjenester med desentraliserte alternativer.\n\n## Hva er DeFi?\n\nDeFi (Decentralized Finance) er et økosystem av finansielle applikasjoner som kjører på blokkjeder:\n\n- **Lån og utlån** — låne penger uten bank\n- **Bytte (swapping)** — bytte én krypto mot en annen\n- **Yield farming** — tjene renter på kryptoen din\n- **Forsikring** — desentraliserte forsikringsløsninger\n\n## Hvordan fungerer DeFi?\n\nDeFi bruker **smarte kontrakter** (smart contracts):\n\n- Selvutførende kode på blokkjeden\n- Ingen mellomledd (bank, megler)\n- Gjennomsiktig og åpen for alle\n- Du trenger bare en lommebok (f.eks. Metamask)\n\n## Populære DeFi-plattformer\n\n- **Uniswap** — desentralisert børs for bytte av tokens\n- **Aave** — lån og utlån av krypto\n- **Curve** — stabilmynt-bytte med lavt gebyr\n- **Lido** — staking av Ethereum\n\n## Risikoer med DeFi\n\n- **Smart contract risiko** — feil i koden kan føre til tap\n- **Impermanent loss** — tap ved å tilby likviditet\n- **Hacks** — DeFi-protokoller har blitt hacket for milliarder\n\n> 🌐 **Husk:** "Not your keys, not your coins." I DeFi har du full kontroll — og fullt ansvar.',
        E'# DeFi — Decentralized Finance\n\nDeFi is one of the most exciting innovations in the crypto world. It is about replacing traditional financial services with decentralized alternatives.\n\n## What is DeFi?\n\nDeFi (Decentralized Finance) is an ecosystem of financial applications running on blockchains:\n\n- **Lending and borrowing** — borrow money without a bank\n- **Swapping** — exchange one crypto for another\n- **Yield farming** — earn interest on your crypto\n- **Insurance** — decentralized insurance solutions\n\n## How does DeFi work?\n\nDeFi uses **smart contracts**:\n\n- Self-executing code on the blockchain\n- No intermediaries (bank, broker)\n- Transparent and open to everyone\n- You only need a wallet (e.g., Metamask)\n\n## Popular DeFi platforms\n\n- **Uniswap** — decentralized exchange for swapping tokens\n- **Aave** — lending and borrowing crypto\n- **Curve** — stablecoin swapping with low fees\n- **Lido** — Ethereum staking\n\n## Risks with DeFi\n\n- **Smart contract risk** — bugs in code can lead to losses\n- **Impermanent loss** — loss from providing liquidity\n- **Hacks** — DeFi protocols have been hacked for billions\n\n> 🌐 **Remember:** "Not your keys, not your coins." In DeFi you have full control — and full responsibility.',
        12, 7, true);
    END IF;
END $$;

-- ============================================================================
-- 7. SEED: course_lessons for Avansert (10 leksjoner)
-- ============================================================================
DO $$
DECLARE
    v_module_id UUID;
BEGIN
    SELECT id INTO v_module_id FROM course_modules WHERE slug = 'avansert';

    IF v_module_id IS NOT NULL THEN
        INSERT INTO course_lessons (module_id, slug, title_no, title_en, content_no, content_en, estimated_minutes, sort_order, is_published) VALUES

        (v_module_id, 'derivater-og-futures', 'Derivater og Futures', 'Derivatives and Futures',
        E'# Derivater og Futures\n\nFutures-kontrakter lar deg handle med giring og tjene på både opp- og nedgående markeder.\n\n## Hva er futures?\n\nEn futureskontrakt er en avtale om å kjøpe eller selge en eiendel til en bestemt pris på en bestemt fremtidig dato:\n\n- **Long** — du tror prisen vil stige\n- **Short** — du tror prisen vil falle\n- **Giring (leverage)** — du handler med lånte penger\n\n## Fordeler og ulemper\n\n### Fordeler\n- Tjene penger på fallende markeder (short)\n- Giring kan forsterke gevinsten\n- Høy likviditet på store børsen\n\n### Ulemper\n- Giring forsterker også TAP\n- Likvideringsrisiko (tvangssalg) ved store bevegelser\n- Krever mer kunnskap og overvåking\n\n## Funding rate\n\nI perpetual futures betaler long- eller short-siden en funding rate:\n\n- **Positiv funding** — longs betaler shorts (markedet er bullish)\n- **Negativ funding** — shorts betaler longs (markedet er bearish)\n\n> ⚠️ **Advarsel:** Futures er IKKE for nybegynnere. Start med 2-3x giring maksimalt.',
        E'# Derivatives and Futures\n\nFutures contracts let you trade with leverage and profit from both rising and falling markets.\n\n## What are futures?\n\nA futures contract is an agreement to buy or sell an asset at a specific price on a specific future date:\n\n- **Long** — you believe the price will rise\n- **Short** — you believe the price will fall\n- **Leverage** — you trade with borrowed money\n\n## Pros and cons\n\n### Pros\n- Make money on falling markets (short)\n- Leverage can amplify gains\n- High liquidity on major exchanges\n\n### Cons\n- Leverage also amplifies LOSSES\n- Liquidation risk (forced sale) on big moves\n- Requires more knowledge and monitoring\n\n## Funding rate\n\nIn perpetual futures, either the long or short side pays a funding rate:\n\n- **Positive funding** — longs pay shorts (market is bullish)\n- **Negative funding** — shorts pay longs (market is bearish)\n\n> ⚠️ **Warning:** Futures are NOT for beginners. Start with max 2-3x leverage.',
        15, 1, true),

        (v_module_id, 'smarte-kontrakter', 'Smarte Kontrakter', 'Smart Contracts',
        E'# Smarte Kontrakter\n\nSmarte kontrakter er selvutførende programmer på blokkjeden — de utgjør ryggraden i DeFi og Web3.\n\n## Hva er en smart kontrakt?\n\nEn smart kontrakt er kode som kjører på blokkjeden og utfører seg selv når betingelser er oppfylt:\n\n```solidity\n// Enkel smart kontrakt i Solidity\ncontract Vault {\n    mapping(address => uint) public balances;\n\n    function deposit() public payable {\n        balances[msg.sender] += msg.value;\n    }\n\n    function withdraw(uint amount) public {\n        require(balances[msg.sender] >= amount);\n        balances[msg.sender] -= amount;\n        payable(msg.sender).transfer(amount);\n    }\n}\n```\n\n## Fordeler\n\n- **Tillitsløs** — du trenger ikke stole på en motpart\n- **Uforanderlig** — når deployet, kan ikke koden endres\n- **Gjennomsiktig** — alle kan lese koden\n- **Kompilerbar** — kan kombineres med andre kontrakter\n\n## Vanlige bruksområder\n\n- **ERC-20 tokens** — nye kryptovalutaer\n- **NFTs** — unike digitale samleobjekter (ERC-721)\n- **DEXes** — desentraliserte børsen (Uniswap)\n- **DAOer** — desentraliserte organisasjoner\n\n## Risikoer\n\n- **Sårbarheter** — reentrancy, overflow, frontrunning\n- **Oraklproblemer** — feil i data fra omverdenen\n- **Upgradable contracts** — proxy-mønsteret introduserer sentralisering\n\n> 💻 **Visste du?** Ethereum\'s ERC-721 standard for NFTs har ført til et helt nytt økosystem for digital kunst og samleobjekter.',
        E'# Smart Contracts\n\nSmart contracts are self-executing programs on the blockchain — they form the backbone of DeFi and Web3.\n\n## What is a smart contract?\n\nA smart contract is code that runs on the blockchain and executes itself when conditions are met:\n\n```solidity\n// Simple smart contract in Solidity\ncontract Vault {\n    mapping(address => uint) public balances;\n\n    function deposit() public payable {\n        balances[msg.sender] += msg.value;\n    }\n\n    function withdraw(uint amount) public {\n        require(balances[msg.sender] >= amount);\n        balances[msg.sender] -= amount;\n        payable(msg.sender).transfer(amount);\n    }\n}\n```\n\n## Benefits\n\n- **Trustless** — you don\'t need to trust a counterparty\n- **Immutable** — once deployed, the code cannot be changed\n- **Transparent** — anyone can read the code\n- **Composable** — can be combined with other contracts\n\n## Common use cases\n\n- **ERC-20 tokens** — new cryptocurrencies\n- **NFTs** — unique digital collectibles (ERC-721)\n- **DEXes** — decentralized exchanges (Uniswap)\n- **DAOs** — decentralized autonomous organizations\n\n## Risks\n\n- **Vulnerabilities** — reentrancy, overflow, frontrunning\n- **Oracle problems** — incorrect data from the outside world\n- **Upgradable contracts** — proxy pattern introduces centralization\n\n> 💻 **Did you know?** Ethereum\'s ERC-721 standard for NFTs has spawned an entire ecosystem of digital art and collectibles.',
        15, 2, true),

        (v_module_id, 'yield-farming', 'Yield Farming og Staking', 'Yield Farming and Staking',
        E'# Yield Farming og Staking\n\nLa kryptoen din jobbe for deg ved å tjene avkastning på beholdningen din.\n\n## Staking\n\nVed å "satse" (stake) myntene dine bidrar du til å sikre blokkjeden og tjener belønning:\n\n- **Ethereum (ETH)** — 3-5% årlig (via Lido eller direkte)\n- **Solana (SOL)** — 6-8% årlig\n- **Cardano (ADA)** — 3-5% årlig\n- **Polkadot (DOT)** — 10-14% årlig\n\n## Yield Farming\n\nYield farming er en mer aktiv form for avkastning:\n\n- Du låner ut kryptoen din via DeFi-protokoller\n- Du tjener gebyrer og governance-tokens\n- Avkastningen varierer, men kan være 5-100%+ årlig\n\n## Likviditetspooler (LPs)\n\nFor å tjene høyere avkastning kan du tilby likviditet:\n\n- Sett inn to tokens i en pool (f.eks. ETH/USDC)\n- Tradere kan bytte mellom dem (mot et gebyr)\n- Du tjener en andel av gebyrene\n\n## Impermanent Loss\n\nNår prisen på de to tokenene i poolen endrer seg, oppstår impermanent loss:\n\n- Hvis ETH stiger mye mot USDC, taper du verdi vs. å bare holde ETH\n- Impermanent loss kan overskygge gebyrinntektene\n- Velg pools med stablecoins for minimal risiko\n\n> 💰 **Tips:** Yield farming er ikke passiv inntekt — det krever aktiv overvåking og forståelse av risiko.',
        E'# Yield Farming and Staking\n\nPut your crypto to work by earning returns on your holdings.\n\n## Staking\n\nBy "staking" your coins, you help secure the blockchain and earn rewards:\n\n- **Ethereum (ETH)** — 3-5% annual (via Lido or directly)\n- **Solana (SOL)** — 6-8% annual\n- **Cardano (ADA)** — 3-5% annual\n- **Polkadot (DOT)** — 10-14% annual\n\n## Yield Farming\n\nYield farming is a more active form of earning:\n\n- You lend your crypto via DeFi protocols\n- You earn fees and governance tokens\n- Returns vary, but can be 5-100%+ annual\n\n## Liquidity Pools (LPs)\n\nTo earn higher returns, you can provide liquidity:\n\n- Deposit two tokens into a pool (e.g. ETH/USDC)\n- Traders can swap between them (for a fee)\n- You earn a share of the fees\n\n## Impermanent Loss\n\nWhen the price of the two tokens in the pool changes, impermanent loss occurs:\n\n- If ETH rises a lot against USDC, you lose value vs. just holding ETH\n- Impermanent loss can overshadow fee income\n- Choose stablecoin pools for minimal risk\n\n> 💰 **Tip:** Yield farming is not passive income — it requires active monitoring and understanding of risk.',
        15, 3, true),

        (v_module_id, 'arbitrage', 'Arbitrage og Markedsineffisiens', 'Arbitrage and Market Inefficiency',
        E'# Arbitrage og Markedsineffisiens\n\nArbitrage er kunsten å tjene penger på prisforskjeller mellom ulike markeder.\n\n## Hva er arbitrage?\n\nNår samme eiendel har ulik pris på ulike børsen, kan du kjøpe billig og selge dyrt:\n\n- **Eksempel:** Bitcoin koster 500 000 kr på Børs A og 505 000 kr på Børs B\n- **Handling:** Kjøp på Børs A, selg på Børs B = 5 000 kr gevinst (minus gebyrer)\n\n## Typer arbitrage\n\n### CEI (Centralized Exchange Arbitrage)\n- Mellom sentraliserte børsen (Binance vs Coinbase)\n- Krever at du har konto og saldo på begge\n\n### DEI (Decentralized Exchange Arbitrage)\n- Mellom DEXer som Uniswap, SushiSwap, Curve\n- Kan gjøres automatisk med bots\n\n### Triangular Arbitrage\n- Utnytter prisforskjeller mellom tre handelspar\n- F.eks. BTC→ETH→USDT→BTC\n- Krever lynraske algoritmer\n\n## Utfordringer\n\n- Arbitragemuligheter varer ofte brøkdeler av et sekund\n- Transaksjonsgebyrer spiser fort opp gevinsten\n- Du trenger kapital på flere plattformer samtidig\n- Bots og instituSjonelle aktører dominerer markedet\n\n> 🤖 **Merk:** Manuell arbitrage er vanskelig. De beste mulighetene fanges av automatiserte bots.',
        E'# Arbitrage and Market Inefficiency\n\nArbitrage is the art of profiting from price differences between different markets.\n\n## What is arbitrage?\n\nWhen the same asset has different prices on different exchanges, you can buy low and sell high:\n\n- **Example:** Bitcoin costs 500,000 NOK on Exchange A and 505,000 NOK on Exchange B\n- **Action:** Buy on Exchange A, sell on Exchange B = 5,000 NOK profit (minus fees)\n\n## Types of arbitrage\n\n### CEI (Centralized Exchange Arbitrage)\n- Between centralized exchanges (Binance vs Coinbase)\n- Requires accounts and balances on both\n\n### DEI (Decentralized Exchange Arbitrage)\n- Between DEXes like Uniswap, SushiSwap, Curve\n- Can be done automatically with bots\n\n### Triangular Arbitrage\n- Exploits price differences between three trading pairs\n- E.g. BTC→ETH→USDT→BTC\n- Requires lightning-fast algorithms\n\n## Challenges\n\n- Arbitrage opportunities often last fractions of a second\n- Transaction fees quickly eat up profits\n- You need capital on multiple platforms simultaneously\n- Bots and institutional players dominate the market\n\n> 🤖 **Note:** Manual arbitrage is difficult. The best opportunities are captured by automated bots.',
        12, 4, true),

        (v_module_id, 'avanserte-indikatorer', 'Avanserte Indikatorer', 'Advanced Indicators',
        E'# Avanserte Indikatorer\n\nEtter å ha lært grunnleggende indikatorer, er det på tide å utforske mer avanserte verktøy.\n\n## Fibonacci Retracement\n\nFibonacci-nivåer hjelper å identifisere potensielle støtte- og motstandsnivåer:\n\n- **23.6%** — grunnleggende korreksjon\n- **38.2%** — vanlig korreksjon i sterke trender\n- **50.0%** — psykologisk nivå (ikke ekte Fibonacci)\n- **61.8%** — "Golden ratio", viktig nivå\n- **78.6%** — dyp korreksjon\n\nNøkkelnivåer å følge med på: 0.382, 0.500, 0.618\n\n## Ichimoku Cloud\n\nEt komplett indikatorsystem som viser:\n\n- **Støtte/motstand** — skyggen (Kumo) fungerer som dynamisk støtte\n- **Trendretning** — prisen over skyen = bullish, under = bearish\n- **Momentum** — senspan (Chikou) linje\n- **Bevegelse** — konversjon og base linjer (Tenkan/Kijun)\n\n## Volume Profile\n\nViser til hvilke priser mest handel har skjedd:\n\n- **High Volume Nodes (HVN)** — områder med mye handel (støtte/motstand)\n- **Low Volume Nodes (LVN)** — områder med lite handel (prisen glir lett)\n- **Point of Control (POC)** — prisen med mest volum\n\n## On-Chain Analysis\n\nAnalyser blokkjededata direkte:\n\n- **Exchange flows** — mye innskudd til børsen = salgspress\n- **Active addresses** — flere aktive = sunn trend\n- **Whale movements** — store transaksjoner kan påvirke markedet\n\n> 📊 **Pro tips:** Kombiner on-chain analyse med teknisk analyse for bedre beslutninger.',
        E'# Advanced Indicators\n\nAfter learning basic indicators, it is time to explore more advanced tools.\n\n## Fibonacci Retracement\n\nFibonacci levels help identify potential support and resistance levels:\n\n- **23.6%** — basic correction\n- **38.2%** — common correction in strong trends\n- **50.0%** — psychological level (not true Fibonacci)\n- **61.8%** — "Golden ratio", important level\n- **78.6%** — deep correction\n\nKey levels to watch: 0.382, 0.500, 0.618\n\n## Ichimoku Cloud\n\nA complete indicator system that shows:\n\n- **Support/resistance** — the cloud (Kumo) acts as dynamic support\n- **Trend direction** — price above cloud = bullish, below = bearish\n- **Momentum** — lagging (Chikou) line\n- **Movement** — conversion and base lines (Tenkan/Kijun)\n\n## Volume Profile\n\nShows at which prices most trading has occurred:\n\n- **High Volume Nodes (HVN)** — areas with lots of trade (support/resistance)\n- **Low Volume Nodes (LVN)** — areas with little trade (price glides easily)\n- **Point of Control (POC)** — the price with the most volume\n\n## On-Chain Analysis\n\nAnalyze blockchain data directly:\n\n- **Exchange flows** — large deposits to exchanges = selling pressure\n- **Active addresses** — more active = healthy trend\n- **Whale movements** — large transactions can affect the market\n\n> 📊 **Pro tip:** Combine on-chain analysis with technical analysis for better decisions.',
        15, 5, true),

        (v_module_id, 'order-flow-analyse', 'Order Flow Analyse', 'Order Flow Analysis',
        E'# Order Flow Analyse\n\nOrder flow er studiet av individuelle ordrer i markedet — et av de kraftigste verktøyene for profesjonelle tradere.\n\n## Hva er Order Flow?\n\nMens teknisk analyse ser på priser, ser ordre flow på selve transaksjonene:\n\n- **Market orders** — aggressive kjøpere/selgere som tar likviditet\n- **Limit orders** — passive kjøpere/selgere som gir likviditet\n- **Order book** — alle ventende ordrer på ulike priser\n\n## Delta\n\nDelta = Kjøpsvolum - Salgsvolum:\n\n- **Positiv delta** — flere aggressive kjøpere enn selgere\n- **Negativ delta** — flere aggressive selgere enn kjøpere\n- **Delta-divergens** — prisen stiger men delta faller (svakhet)\n\n## CVD (Cumulative Volume Delta)\n\nDen løpende summen av delta over tid:\n\n- CVD som stiger = kjøpstrykk\n- CVD som faller = salgstrykk\n- CVD-divergens fra prisen = potensiell reversering\n\n## Footprint Charts\n\nViser kjøps- og salgsvolum på hvert prisnivå:\n\n- **Bid x Ask** — hvor mye som ble kjøpt og solgt på hver pris\n- **POC** — prisnivå med mest volum\n- **High volume nodes** — områder med stor interesse\n\n> 🕵️ **Pro tip:** Order flow gir deg et forsprang på de fleste tradere som kun ser på prisen.',
        E'# Order Flow Analysis\n\nOrder flow is the study of individual orders in the market — one of the most powerful tools for professional traders.\n\n## What is Order Flow?\n\nWhile technical analysis looks at prices, order flow looks at the actual transactions:\n\n- **Market orders** — aggressive buyers/sellers taking liquidity\n- **Limit orders** — passive buyers/sellers providing liquidity\n- **Order book** — all waiting orders at various prices\n\n## Delta\n\nDelta = Buy Volume - Sell Volume:\n\n- **Positive delta** — more aggressive buyers than sellers\n- **Negative delta** — more aggressive sellers than buyers\n- **Delta divergence** — price rises but delta falls (weakness)\n\n## CVD (Cumulative Volume Delta)\n\nThe running sum of delta over time:\n\n- CVD rising = buying pressure\n- CVD falling = selling pressure\n- CVD divergence from price = potential reversal\n\n## Footprint Charts\n\nShows buying and selling volume at each price level:\n\n- **Bid x Ask** — how much was bought and sold at each price\n- **POC** — price level with most volume\n- **High volume nodes** — areas of high interest\n\n> 🕵️ **Pro tip:** Order flow gives you an edge over most traders who only look at price.',
        15, 6, true),

        (v_module_id, 'psykologi', 'Trading Psykologi', 'Trading Psychology',
        E'# Trading Psykologi\n\nDe fleste tradere taper penger ikke på grunn av dårlige strategier, men på grunn av dårlig psykologi.\n\n## De største fellene\n\n### FOMO (Fear Of Missing Out)\n- Ser andre tjene penger og hopper inn uten plan\n- Kjøper på toppen, selger på bunnen\n- **Løsning:** Følg din plan, ikke andres gevinster\n\n### Panikk-salg\n- Prisen faller 10% og du selger i panikk\n- Dagen etter stiger den 20%\n- **Løsning:** Bruk stop loss, ikke følelser\n\n### Overhandel\n- Føler at du MÅ handle hver dag\n- Betaler gebyrer og taper på dårlige entries\n- **Løsning:** Kvalitet over kvantitet. Vent på dine beste set-ups.\n\n## Mental reset\n\nEtter en tapende trade:\n\n1. Ta en pause (minst 30 min)\n2. Analyser hva som gikk galt uten følelser\n3. Godta tapet — det er en kostnad ved å lære\n4. Ikke prøv å "hevne" (revenge trade)\n\n## Journalføring\n\nFør en trade-journal:\n\n- Hvorfor gikk du inn?\n- Hva var stop loss/take profit?\n- Hvordan følte du deg?\n- Hva lærte du?\n\n> 🧠 **Husk:** Trading er et mentalt spill. En disiplinert trader med en dårlig strategi vil tjene mer enn en udisiplinert trader med en god strategi.',
        E'# Trading Psychology\n\nMost traders lose money not because of bad strategies, but because of bad psychology.\n\n## The biggest traps\n\n### FOMO (Fear Of Missing Out)\n- See others making money and jump in without a plan\n- Buy the top, sell the bottom\n- **Solution:** Follow your plan, not others\' gains\n\n### Panic selling\n- Price drops 10% and you sell in panic\n- The next day it rises 20%\n- **Solution:** Use stop loss, not emotions\n\n### Overtrading\n- Feel you MUST trade every day\n- Pay fees and lose on bad entries\n- **Solution:** Quality over quantity. Wait for your best set-ups.\n\n## Mental reset\n\nAfter a losing trade:\n\n1. Take a break (at least 30 min)\n2. Analyze what went wrong without emotions\n3. Accept the loss — it is a cost of learning\n4. Don\'t try to "revenge trade"\n\n## Journal keeping\n\nKeep a trade journal:\n\n- Why did you enter?\n- What was stop loss/take profit?\n- How did you feel?\n- What did you learn?\n\n> 🧠 **Remember:** Trading is a mental game. A disciplined trader with a bad strategy will make more money than an undisciplined trader with a good strategy.',
        10, 7, true),

        (v_module_id, 'automatisert-handel', 'Automatisert Handel og Bots', 'Automated Trading and Bots',
        E'# Automatisert Handel og Bots\n\nAutomatisert trading lar deg handle 24/7 uten å måtte overvåke skjermen konstant.\n\n## Hvorfor automatisere?\n\n- **Fjerner følelser** — boten følger strategien uten frykt/grådighet\n- **24/7 tilstedeværelse** — markedet sover aldri, men du gjør det\n- **Raske reaksjoner** — boten handler på millisekunder\n- **Backtesting** — test strategien på historiske data før du kjører den live\n\n## Typer trading bots\n\n### Market Making Bots\n- Setter limitordre på begge sider av orderboken\n- Tjener på spreaden (differansen mellom kjøp og salg)\n\n### Trend-følgende Bots\n- Kjøper i opptrend, selger i nedtrend\n- Bruker glidende gjennomsnitt eller trendlinjer\n\n### Arbitrage Bots\n- Utnytter prisforskjeller mellom børsen\n- Krever lynrask infrastruktur\n\n## Klarpakke SmartTrader\n\nKlarpakke har en innebygd automatisk trader:\n\n- RSI(14) + SMA(9/21) + momentum indikatorer\n- Kjøper ved oversolgte forhold, selger ved overkjøpte\n- Kun paper trading (virtuelle penger)\n- Du aktiverer den per trading session\n\n## Viktige hensyn\n\n- Backtesting kan være misvisende (overfitting)\n- Bots kan tape penger raskt i volatile markeder\n- Overvåk boten — den er ikke "set and forget"\n\n> 🤖 **Klarpakke:** Prøv SmartTrader i dashboardet. Aktiver den på en paper-trading session for å se hvordan den fungerer.',
        E'# Automated Trading and Bots\n\nAutomated trading lets you trade 24/7 without having to constantly monitor the screen.\n\n## Why automate?\n\n- **Removes emotions** — the bot follows the strategy without fear/greed\n- **24/7 presence** — the market never sleeps, but you do\n- **Fast reactions** — the bot trades in milliseconds\n- **Backtesting** — test the strategy on historical data before running it live\n\n## Types of trading bots\n\n### Market Making Bots\n- Places limit orders on both sides of the order book\n- Earns on the spread (difference between buy and sell)\n\n### Trend-following Bots\n- Buy in uptrend, sell in downtrend\n- Uses moving averages or trend lines\n\n### Arbitrage Bots\n- Exploits price differences between exchanges\n- Requires lightning-fast infrastructure\n\n## Klarpakke SmartTrader\n\nKlarpakke has a built-in automated trader:\n\n- RSI(14) + SMA(9/21) + momentum indicators\n- Buys on oversold conditions, sells on overbought\n- Paper trading only (virtual money)\n- You activate it per trading session\n\n## Important considerations\n\n- Backtesting can be misleading (overfitting)\n- Bots can lose money fast in volatile markets\n- Monitor the bot — it is not "set and forget"\n\n> 🤖 **Klarpakke:** Try SmartTrader in the dashboard. Activate it on a paper trading session to see how it works.',
        15, 8, true),

        (v_module_id, 'makroanalyse', 'Makroanalyse og Korrelasjoner', 'Macro Analysis and Correlations',
        E'# Makroanalyse og Korrelasjoner\n\nKryptovaluta påvirkes i økende grad av makroøkonomiske faktorer.\n\n## Makroøkonomiske faktorer\n\n### Renter (Fed Funds Rate)\n- Lave renter = mer risikovillig kapital = krypto stiger\n- Høye renter = investorer trekker seg til sikre havner = krypto faller\n\n### Inflasjon\n- Høy inflasjon kan være bra for Bitcoin (digitalt gull)\n- Men Fed må øke renten for å bekjempe inflasjon (se over)\n\n### Dollar Index (DXY)\n- Når dollaren styrkes, faller ofte krypto\n- Når dollaren svekkes, stiger ofte krypto\n\n## Korrelasjon med tradisjonelle markeder\n\nKrypto har blitt mer korrelert med aksjemarkedet over tid:\n\n- **S&P 500** — moderat positiv korrelasjon\n- **Nasdaq** — sterkere korrelasjon (spesielt tech-tunge mynter)\n- **Gull** — lav korrelasjon (noen ganger negativ)\n\n## Kryptospesifikke hendelser\n\n- **Halving** — Bitcoin-halvering hvert 4. år (historisk etterfulgt av bull run)\n- **ETF-nyheter** — godkjenning av Bitcoin ETF gir ofte oppgang\n- **Regulering** — strengere regulering gir ofte nedgang\n- **Hacks** — store børshack kan svekke tilliten\n\n## Kalender\n\nFølg med på:\n\n- FOMC-møter (rentebeslutninger)\n- CPI-rapporter (inflasjon)\n- Bitcoin halving (hvert 4. år)\n- Blockchain-konferanser\n\n> 🌍 **Makro trader:** Forståelse av makroøkonomi gir deg et stort forsprang på tradere som bare ser på kryptosykluser.',
        E'# Macro Analysis and Correlations\n\nCryptocurrency is increasingly affected by macroeconomic factors.\n\n## Macroeconomic factors\n\n### Interest rates (Fed Funds Rate)\n- Low rates = more risk capital = crypto rises\n- High rates = investors retreat to safe havens = crypto falls\n\n### Inflation\n- High inflation can be good for Bitcoin (digital gold)\n- But the Fed must raise rates to combat inflation (see above)\n\n### Dollar Index (DXY)\n- When the dollar strengthens, crypto often falls\n- When the dollar weakens, crypto often rises\n\n## Correlation with traditional markets\n\nCrypto has become more correlated with the stock market over time:\n\n- **S&P 500** — moderate positive correlation\n- **Nasdaq** — stronger correlation (especially tech-heavy coins)\n- **Gold** — low correlation (sometimes negative)\n\n## Crypto-specific events\n\n- **Halving** — Bitcoin halving every 4 years (historically followed by bull run)\n- **ETF news** — Bitcoin ETF approval often brings gains\n- **Regulation** — stricter regulation often brings declines\n- **Hacks** — major exchange hacks can weaken confidence\n\n## Calendar\n\nFollow:\n\n- FOMC meetings (interest rate decisions)\n- CPI reports (inflation)\n- Bitcoin halving (every 4 years)\n- Blockchain conferences\n\n> 🌍 **Macro trader:** Understanding macroeconomics gives you a major edge over traders who only look at crypto cycles.',
        12, 9, true),

        (v_module_id, 'egne-strategier', 'Bygge Egne Strategier', 'Building Your Own Strategies',
        E'# Bygge Egne Strategier\n\nDu har nå kunnskapen til å bygge dine egne tradingstrategier. Her er en rammeverk for å utvikle dem.\n\n## Steg 1: Definer mål\n\nHva vil du oppnå?\n\n- **Kortsiktig** — day trading (minutter/timer)\n- **Mellomlang** — swing trading (dager/uker)\n- **Langsiktig** — buy and hold (måneder/år)\n\n## Steg 2: Velg markeder\n\nHva vil du handle?\n\n- **Store mynter** (BTC, ETH) — mindre volatilt, mer forutsigbart\n- **Mid-cap** (SOL, ADA) — høyere risiko, høyere belønning\n- **Small-cap** — svært spekulativt\n\n## Steg 3: Utvikle regler\n\nEn god strategi har klare regler:\n\n- **Entry** — når går du inn? (indikator X krysser nivå Y og volum er Z)\n- **Exit** — når går du ut? (take profit på nivå A, stop loss på nivå B)\n- **Position size** — hvor mye risikerer du? (1% av porteføljen)\n\n## Steg 4: Backtest\n\nTest strategien på historiske data:\n\n- Bruk TradingView eller lignende verktøy\n- Minst 100 trades for statistisk signifikans\n- Sjekk: win rate, profit factor, max drawdown, Sharpe ratio\n\n## Steg 5: Paper trade\n\nKjør strategien med virtuelle penger først:\n\n- Minst 20-50 trades\n- Juster parametre basert på resultater\n- Før journal over hver trade\n\n## Steg 6: Live med små beløp\n\nNår du er trygg:\n\n- Start med minimumsbeløp\n- Øk gradvis når du ser konsistente resultater\n- Aldri endre strategien midt i en trade\n\n> 🎯 **Siste tips:** Den beste strategien er den du faktisk følger. Enkelhet er nøkkelen til konsistens.',
        E'# Building Your Own Strategies\n\nYou now have the knowledge to build your own trading strategies. Here is a framework to develop them.\n\n## Step 1: Define goals\n\nWhat do you want to achieve?\n\n- **Short-term** — day trading (minutes/hours)\n- **Medium-term** — swing trading (days/weeks)\n- **Long-term** — buy and hold (months/years)\n\n## Step 2: Choose markets\n\nWhat do you want to trade?\n\n- **Large coins** (BTC, ETH) — less volatile, more predictable\n- **Mid-cap** (SOL, ADA) — higher risk, higher reward\n- **Small-cap** — very speculative\n\n## Step 3: Develop rules\n\nA good strategy has clear rules:\n\n- **Entry** — when do you enter? (indicator X crosses level Y and volume is Z)\n- **Exit** — when do you exit? (take profit at level A, stop loss at level B)\n- **Position size** — how much do you risk? (1% of portfolio)\n\n## Step 4: Backtest\n\nTest the strategy on historical data:\n\n- Use TradingView or similar tools\n- At least 100 trades for statistical significance\n- Check: win rate, profit factor, max drawdown, Sharpe ratio\n\n## Step 5: Paper trade\n\nRun the strategy with virtual money first:\n\n- At least 20-50 trades\n- Adjust parameters based on results\n- Keep a journal of each trade\n\n## Step 6: Live with small amounts\n\nWhen you are confident:\n\n- Start with minimum amounts\n- Increase gradually when you see consistent results\n- Never change the strategy mid-trade\n\n> 🎯 **Final tip:** The best strategy is the one you actually follow. Simplicity is the key to consistency.',
        15, 10, true);
    END IF;
END $$;

-- ============================================================================
-- 8. SEED: Badges for each course
-- ============================================================================
DO $$
DECLARE
    v_nybegynner_id UUID;
    v_middels_id UUID;
    v_avansert_id UUID;
BEGIN
    SELECT id INTO v_nybegynner_id FROM course_modules WHERE slug = 'nybegynner';
    SELECT id INTO v_middels_id FROM course_modules WHERE slug = 'middels';
    SELECT id INTO v_avansert_id FROM course_modules WHERE slug = 'avansert';

    INSERT INTO course_badges (module_id, badge_emoji, badge_label_no, badge_label_en, badge_description_no, badge_description_en, badge_color) VALUES
    (v_nybegynner_id, '🌱', 'Krypto Spire', 'Crypto Sprout', 'Fullførte Nybegynner-kurset. Har lært det grunnleggende om krypto.', 'Completed the Beginner course. Has learned the basics of crypto.', 'from-emerald-500 to-teal-600'),
    (v_middels_id, '📊', 'Markedsanalytiker', 'Market Analyst', 'Fullførte Middels-kurset. Forstår markedsanalyse, risiko og DeFi.', 'Completed the Intermediate course. Understands market analysis, risk and DeFi.', 'from-blue-500 to-indigo-600'),
    (v_avansert_id, '💎', 'Krypto Ekspert', 'Crypto Expert', 'Fullførte Avansert-kurset. Mester i trading, yield farming og avanserte strategier.', 'Completed the Advanced course. Master of trading, yield farming and advanced strategies.', 'from-amber-500 to-purple-600')
    ON CONFLICT (module_id) DO NOTHING;
END $$;
